import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CRFziyHp.js";const o="/images/placeholder-rider-dispatch-monitor.svg",i="/images/placeholder-takeaway-merchant-admin.svg",f=JSON.parse('{"title":"外卖","description":"","frontmatter":{},"headers":[],"relativePath":"features/takeaway.md","filePath":"features/takeaway.md","lastUpdated":1785013113000}'),s={name:"features/takeaway.md"};function n(d,t,h,g,u,p){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="外卖" tabindex="-1">外卖 <a class="header-anchor" href="#外卖" aria-label="Permalink to &quot;外卖&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置各区域外卖业务规则、审核商家，并管理订单与派单策略。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>外卖模块已在授权中开通（侧栏 <strong>商户管理 → 外卖</strong> 可见）。</li><li><a href="/features/map">高德地图</a> 已配置 Web Key 与安全密钥。</li><li><a href="/features/payment">支付与提现</a> 已配置（用户下单支付）。</li><li><a href="/features/rider">骑手</a> 侧有在线骑手（派单依赖）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-区域外卖配置" tabindex="-1">1. 区域外卖配置 <a class="header-anchor" href="#_1-区域外卖配置" aria-label="Permalink to &quot;1. 区域外卖配置&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 区域外卖配置</strong></p><p>按区域设置：</p><ul><li>是否开通外卖</li><li>配送范围、起送价、配送费</li><li><strong>派单策略</strong>（自动派单 / 抢单模式、超时转派等，以页面选项为准）</li><li>营业时段、平台抽佣相关参数</li></ul><p>此为外卖核心配置，新区域上线必做。</p><h3 id="_2-佣金配置" tabindex="-1">2. 佣金配置 <a class="header-anchor" href="#_2-佣金配置" aria-label="Permalink to &quot;2. 佣金配置&quot;">​</a></h3><p>路径：<strong>商户管理 → 外卖 → 佣金配置</strong></p><p>平台与商家之间的佣金比例、结算规则。</p><h3 id="_3-商家入驻" tabindex="-1">3. 商家入驻 <a class="header-anchor" href="#_3-商家入驻" aria-label="Permalink to &quot;3. 商家入驻&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>商家审核</strong></td><td>处理商家入驻申请</td></tr><tr><td><strong>商家管理</strong></td><td>维护已入驻店铺、营业状态</td></tr><tr><td><strong>商品分类 / 商品管理 / 规格小料</strong></td><td>代商家或协助维护菜单</td></tr><tr><td><strong>桌码管理</strong></td><td>堂食扫码点餐（如启用）</td></tr></tbody></table><h3 id="_4-订单与收益" tabindex="-1">4. 订单与收益 <a class="header-anchor" href="#_4-订单与收益" aria-label="Permalink to &quot;4. 订单与收益&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>外卖订单</strong></td><td>查询、处理异常订单</td></tr><tr><td><strong>平台收益</strong></td><td>查看平台佣金收入</td></tr></tbody></table><p><img src="'+o+'" alt="外卖派单监控示意"></p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>外卖业务 <strong>按区域独立</strong>：每个 region_id 在 <strong>区域外卖配置</strong> 中单独一行。</p><ul><li>未开通区域：用户端无外卖入口</li><li>派单策略、配送半径仅影响本区域订单</li></ul><p>跑腿订单在 <strong>商户管理 → 外卖 → 跑腿订单</strong> 查看，区域规则见 <a href="/features/errand">跑腿</a>。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>区域外卖配置</strong> 中开启测试区域并设置配送范围。</li><li><strong>商家审核</strong> 通过一家测试店铺，商家端 / 后台 <strong>商家管理</strong> 中设为营业。</li><li>客户端在该区域下单并支付，<strong>外卖订单</strong> 出现记录。</li><li>有在线骑手时，订单进入派单流程并最终完成（状态以列表为准）。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>商户管理菜单显示「内测中」或无法点击</strong></p><ul><li>外卖功能未开通：到 <strong>系统设置 → 我的模块</strong> 查看是否已解锁，或联系商务开通。</li></ul><p><strong>用户看不到外卖</strong></p><ul><li>该区域 <strong>区域外卖配置</strong> 未启用。</li><li><strong>UI TabBar</strong> 未配置外卖入口。</li><li>当前位置不在配送范围内（检查地图 Key 与配送半径）。</li></ul><p><strong>长时间无人接单</strong></p><ul><li><strong>派单策略</strong> 是否与骑手数量匹配；查看 <strong>骑手管理</strong> 在线人数。</li><li><a href="/features/rider">骑手审核</a> 是否通过足够骑手。</li></ul><p><strong>地图 / 距离错误</strong></p><ul><li>见 <a href="/features/map">地图与定位</a>。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/errand">跑腿</a></li><li><a href="/features/rider">骑手</a></li><li><a href="/features/map">地图与定位</a></li><li><a href="/features/payment">支付与提现</a></li></ul><p><img src="'+i+'" alt="外卖商家后台示意"></p>',37)])])}const b=a(s,[["render",n]]);export{f as __pageData,b as default};
